package br.com.sussmartcare.queue.infrastructure.messaging; import br.com.sussmartcare.queue.application.QueueApplicationService; import br.com.sussmartcare.queue.domain.PresenceState; import com.fasterxml.jackson.databind.*; import java.util.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class PresenceConsumer {private final ObjectMapper mapper;private final ProcessedEventRepository processed;private final QueueApplicationService app;public PresenceConsumer(ObjectMapper m,ProcessedEventRepository p,QueueApplicationService a){mapper=m;processed=p;app=a;}@KafkaListener(topics="patient-presence-changed",groupId="queue-presence")@Transactional public void consume(String raw)throws Exception{var e=mapper.readTree(raw);UUID eventId=UUID.fromString(e.path("eventId").asText());if(processed.existsById(eventId))return;var d=e.path("data");String type=d.path("eventType").asText();PresenceState state=switch(type){case "ENTERED_FACILITY","PATIENT_RETURNED","ENTERED_ZONE"->PresenceState.INSIDE_FACILITY;case "LEFT_FACILITY","LEFT_ZONE"->PresenceState.OUTSIDE_FACILITY;default->PresenceState.UNKNOWN;};app.presence(UUID.fromString(d.path("visitId").asText()),state);processed.save(new ProcessedEvent(eventId,"queue-presence"));}}
